/*====================*
 *  Static functions  *
 *====================*/
static void rtOneStep(RT_MDL_TYPE *S) {
    boolean_T eventFlags[3];
    int_T i;
    for (i = 1; i < 3; i++) {
        eventFlags[i] = rtmStepTask(S, i);
        if (++rtmTaskCounter(S, i) == rtmCounterLimit(S, i)) {
            rtmTaskCounter(S, i) = 0;
        }
    }
    MODEL_STEP(0);
    fmu_RestoreOutput();
    for (i = 1; i < 3; i++) {
        if (eventFlags[i]) {
    MODEL_STEP(i);
        }
    }
}
