    modelData->rList[7] = &(KIMMCar_U.pz_o);
    modelData->rList[8] = &(KIMMCar_U.qx_g);
    modelData->rList[9] = &(KIMMCar_U.qy_i);
    modelData->rList[10] = &(KIMMCar_U.pz_f);
    modelData->rList[11] = &(KIMMCar_U.qx_l);
    modelData->rList[12] = &(KIMMCar_U.qy_a);
    modelData->rList[13] = &(KIMMCar_U.pz_i);
    modelData->rList[14] = &(KIMMCar_U.qx_m);
    modelData->rList[15] = &(KIMMCar_U.qy_b);
    modelData->rList[16] = &(KIMMCar_Y.body_x);
    modelData->rList[17] = &(KIMMCar_Y.body_y);
    modelData->rList[18] = &(KIMMCar_Y.body_z);
    modelData->rList[19] = &(KIMMCar_Y.body_q[0]);
