fmi2Status fmi2SetString (fmi2Component c, const fmi2ValueReference vr[], size_t nvr, const fmi2String value[]) {
    FMUModelData *modelData = (FMUModelData *)c;
    _instance = modelData;
    size_t i;    
    fmi2Boolean is_diff_value = fmi2False;
    size_t size;
    if (nvr != 0 && (!value || !vr)) {
        modelData->functions->logger(modelData->functions->componentEnvironment, modelData->instanceName, 
                    fmi2Error, "error", "invalid memory access");
        return fmi2Error;
    }
    for (i = 0; i < nvr; i++) {
       if (vr[i] >= 0.0) {
            modelData->functions->logger(modelData->functions->componentEnvironment, modelData->instanceName, 
                    fmi2Error, "error", "valueReference out of range");
            return fmi2Error;
        }
    }
    for (i = 0; i < nvr; i++) {
        if (strcmp(modelData->sList[vr[i]], value[i]) != 0) {
            is_diff_value = fmi2True;
            size = strlen(value[i]) < (modelData->sSize[vr[i]] - 1) ? strlen(value[i]) : (modelData->sSize[vr[i]] - 1);
            strncpy(modelData->sList[vr[i]], value[i], size);
            *((char*)modelData->sList[vr[i]]+size) = '\x00';
        }
        if (modelData->loggingOn) {
            modelData->functions->logger(modelData->functions->componentEnvironment, modelData->instanceName, 
               fmi2OK, "info", "setString vr:%d, value:%s", vr[i], value[i]);
        }
    }
    return fmi2OK;
}

fmi2Status fmi2GetFMUstate(fmi2Component c, fmi2FMUstate* FMUstate) {
    FMUModelData *modelData = (FMUModelData *)c;
    _instance = modelData;
    FMUInternalState* fmuInternalState = (FMUInternalState*)calloc(1, sizeof(FMUInternalState));
    memcpy(&fmuInternalState->ExternalInput, &KIMMCar_U, sizeof(ExtU_KIMMCar_T));
    memcpy(&fmuInternalState->ExternalOutput, &KIMMCar_Y, sizeof(ExtY_KIMMCar_T));
    memcpy(&fmuInternalState->Parameter, &KIMMCar_P, sizeof(P_KIMMCar_T));
    memcpy(&fmuInternalState->RTModel, modelData->S, sizeof(RT_MODEL_KIMMCar_T));
    memcpy(&fmuInternalState->blockBuffer, &KIMMCar_B, sizeof(B_KIMMCar_T));
    memcpy(&fmuInternalState->dWork, &KIMMCar_DW, sizeof(DW_KIMMCar_T));
    memcpy(&fmuInternalState->x, &KIMMCar_X, sizeof(X_KIMMCar_T));
    for(size_t i = 0; i < 89; i++) {
        fmuInternalState->rListBuffer[i] = *modelData->rList[i];
    }
    if (KIMMCar_DW.STATE_1_Simulator) {
        fmuInternalState->ssOp[0] = nesl_save_simdata(KIMMCar_DW.STATE_1_Simulator, &fmuInternalState->ssStateSize[0]);
    }
    if (KIMMCar_DW.OUTPUT_1_0_Simulator) {
        fmuInternalState->ssOp[1] = nesl_save_simdata(KIMMCar_DW.OUTPUT_1_0_Simulator, &fmuInternalState->ssStateSize[1]);
    }
    if (KIMMCar_DW.OUTPUT_1_1_Simulator) {
        fmuInternalState->ssOp[2] = nesl_save_simdata(KIMMCar_DW.OUTPUT_1_1_Simulator, &fmuInternalState->ssStateSize[2]);
    }
    fmuInternalState->time = modelData->time;
    if (modelData->loggingOn) {
        modelData->functions->logger(modelData->functions->componentEnvironment, modelData->instanceName, 
           fmi2OK, "info", "FMUstate saved at time %f.", modelData->time);
    }
    *FMUstate = (void*)(fmuInternalState);
    return fmi2OK;
}

